// ESLint 9 flat config for apps/mcp.
//
// R0.1.4 (2026-10-11): the previous `"lint": "echo 'lint deferred to S1'"`
// was a no-op that always returned 0. This file replaces it with a real
// lint check: ESLint 9 with the JS-recommended rules, TypeScript-aware
// only via the project's tsconfig (we deliberately do NOT pull in
// typescript-eslint here — MCP adapter code is short and the JS rules
// catch the smells we care about: unused vars, dead code, suspicious
// equality, etc.).
//
// Ignores:
//   - dist/     build output (gitignored)
//   - *.d.ts    generated by tsc -b during typecheck
//
// The script in package.json runs `eslint .` which fails on any
// `--max-warnings 0` violation. Future hardening (R3 area) can layer
// typescript-eslint and security rules on top of this baseline.

import js from '@eslint/js';

export default [
  {
    ignores: [
      'dist/**',
      '*.d.ts',
      'node_modules/**',
    ],
  },
  js.configs.recommended,
];